const ctx = canvas.getContext('2d');
canvas.width = 400;
canvas.height = 400;

// Set up initial conditions
let theta = 0; // initial angle
let omega = 0; // initial angular velocity
let t = 0; // time
let dt = 0.01; // time step

// Set up button event listener
